import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int[] baholar = Arrays.stream(in.nextLine().trim().split("\\s+")).mapToInt(Integer::parseInt).toArray();
        int n = baholar.length;
        int yaxshi = 0;
        for (int b : baholar) {
            if (b >= 4) yaxshi++;
        }
        System.out.println(String.format("CSAT: %.1f%%", yaxshi * 100.0 / n));
    }
}

solution.cpp:
#include <cstdio>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>
using namespace std;

int main() {
    string satr;
    getline(cin, satr);
    istringstream ss(satr);
    vector<int> baholar;
    int b;
    while (ss >> b) baholar.push_back(b);

    int n = baholar.size();
    int yaxshi = 0;
    for (int x : baholar) {
        if (x >= 4) yaxshi++;
    }
    printf("CSAT: %.1f%%\n", yaxshi * 100.0 / n);
    return 0;
}
